{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Piritrexim, a 2,4-diaminopyrimidine antifolate with a methoxybenzyl substituent, showed absolute oral bioavailability of 63% in a patient; the query shares the 2,4-diaminopyrimidine and methoxyaryl pharmacophore, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Trimazosin, a 4-amino-6,7,8-trimethoxyquinazoline, had oral bioavailability of 63% in healthy men; its methoxy-substituted aminopyrimidine-like core is relevant to the query and supports high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Alfuzosin, a quinazoline derivative with basic amine and methoxyaryl groups, had absolute oral bioavailability of 64.5% in healthy subjects, supporting high F for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Abecarnil, a beta-carboline with an indole-like fused heteroaromatic system, had absolute oral bioavailability of 39 ± 17% in healthy volunteers; the query's chloroindole amide and lipophilic heteroaromatic character align with this high-F example.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Betrixaban, an oral factor Xa inhibitor containing a polar amidine, had absolute oral bioavailability of 34% in humans, demonstrating that polar basic groups do not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Alisertib, an aurora kinase inhibitor with aminopyrimidine, methoxy, and chloroaryl motifs, had bioavailability of 67% in pediatric patients; this is the closest kinase-inhibitor analogue and strongly supports high oral bioavailability for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence points to oral bioavailability above the 20% threshold. The closest analogues with diaminopyrimidine/quinazoline and methoxyaryl features show F values of 34-77%, and even the lowest measured value among relevant analogues (23%) exceeds the threshold. No affirmative experimental evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data are available for the exact query molecule.",
    "Morgan similarities to the evidence molecules are low (~0.2), limiting structural transferability.",
    "Solubility, permeability, and first-pass metabolism of the query have not been directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

